import React, { useState, FormEvent } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxFormField,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
  initialName?: string;
  initialLanguage?: Language;
  initialEmailNotifications?: boolean;
}

export default function ProfileSettingsForm({
  onSave,
  initialName = '',
  initialLanguage = 'ru',
  initialEmailNotifications = true,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialName);
  const [language, setLanguage] = useState<Language>(initialLanguage);
  const [emailNotifications, setEmailNotifications] = useState(initialEmailNotifications);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form className="jx-stack jx-gap-lg" onSubmit={handleSubmit}>
      <JxFormField label="Имя" htmlFor="profile-name">
        <JxTextField
          id="profile-name"
          value={name}
          onValueChange={setName}
          placeholder="Введите имя"
        />
      </JxFormField>

      <JxFormField label="Язык интерфейса" htmlFor="profile-language">
        <JxSelect
          id="profile-language"
          value={language}
          onValueChange={(value) => setLanguage(value as Language)}
        >
          <JxSelectOption value="ru">Русский</JxSelectOption>
          <JxSelectOption value="en">Английский</JxSelectOption>
        </JxSelect>
      </JxFormField>

      <JxFormField label="Уведомления на почту" htmlFor="profile-email-notifications">
        <JxSwitch
          id="profile-email-notifications"
          checked={emailNotifications}
          onCheckedChange={setEmailNotifications}
        />
      </JxFormField>

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

